from pathlib import Path
import re

ROOT=Path(__file__).resolve().parents[2]
DOC=ROOT/'Assets/Experiments/IceResurfacer/Documentation'
old=(DOC/'UI-Phases-1-to-4-Master-Acceptance.md').read_text(encoding='utf-8-sig')
rows=re.findall(r'^\| ((?:[A-I]\d\d|P[34]-[A-Z]\d\d)) \|.*$',old,re.M)
assert len(rows)==218
lines={re.match(r'^\| (\S+) \|',line).group(1):line for line in old.splitlines() if re.match(r'^\| (?:[A-I]\d\d|P[34]-[A-Z]\d\d) \|',line)}
titles=['Project startup and asset integrity','Driving HUD','Machinery console','Surface Survey and minimap','GPS and Route Manager','Welcome and session selection','Pause/settings','Help','Results','Water-service UI','Notifications and warnings','Physical cockpit and mouse interaction','Screen state/modal behavior','Edit Mode preview and authoring','Responsive layouts','Persistence across Unity restart','Procedural fallback scene','Gameplay regression','Performance and allocations','Final visual acceptance']
sections={i:[] for i in range(1,21)}
for key,line in lines.items():
    if key[0] in 'ABCDEFGHI': target={'A':1,'B':2,'C':3,'D':12,'E':15,'F':18,'G':16,'H':17,'I':19}[key[0]]
    elif key.startswith('P3-'): target={'S':4,'G':5,'R':5,'X':13,'P':19}[key[3]]
    else:
        family=key[3]; n=int(key[4:])
        target={'W':6,'S':7,'H':8,'R':9,'I':13,'A':14,'X':13,'P':19}[family]
        if family=='A' and n in (8,9,10): target=15
        if family=='A' and n==4: target=16
        if family=='X': target={1:2,2:3,3:3,4:4,5:5,6:5,7:5,8:5,9:17}[n]
        if family=='P': target={1:1,2:19,3:19,4:16,5:18,6:1}[n]
    sections[target].append(line)

